final class Book {
    private final Supplier<Author> loader;
    private volatile Author author;            // safe publication
    Book(Supplier<Author> loader) { this.loader = loader; }
    Author author() {
        Author a = author;
        if (a == null) synchronized (this) {
            if ((a = author) == null) author = a = loader.get();
        }
        return a;
    }
}

